CREATE TABLE siswa (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nama VARCHAR(100) NOT NULL,
  jurusan VARCHAR(50) DEFAULT 'RPL',
  nilai_quiz INT DEFAULT 0
);

